package com.akira.one;
import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import java.util.*;
public class ListsActivity extends BaseActivity{private final List<ListProfile> items=new ArrayList<>();private ListAdapter adapter;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_lists);RecyclerView rv=findViewById(R.id.listsRecycler);rv.setLayoutManager(new LinearLayoutManager(this));adapter=new ListAdapter(items,p->{Prefs.selectList(this,p);Toast.makeText(this,"Lista selecionada: "+p.name,Toast.LENGTH_SHORT).show();finish();});rv.setAdapter(adapter);load();}private void load(){items.clear();if(Prefs.directMode(this)){items.add(new ListProfile(0,Prefs.directListName(this),"Acesso direto",Prefs.directServerUrl(this),Prefs.directUsername(this),Prefs.directPassword(this),"",true));}else items.addAll(Prefs.lists(this));adapter.notifyDataSetChanged();((TextView)findViewById(R.id.listsStatus)).setText(items.isEmpty()?"Nenhuma lista disponível no painel.":"Selecione a lista que deseja usar");}}
